import json

# New hypothesis: 
# 1. Cells that are part of a 3+ cell horizontal or vertical line are preserved
# 2. Cells on the main diagonals are preserved  
# 3. All non-preserved cells become 1

input_grid = [
    [8, 8, 8, 3, 3, 3, 3, 3, 8],
    [8, 3, 8, 3, 3, 3, 3, 3, 8],
    [3, 3, 8, 8, 8, 3, 8, 8, 3],
    [3, 8, 8, 8, 8, 3, 3, 3, 3],
    [3, 3, 3, 3, 8, 8, 8, 8, 3],
    [8, 3, 8, 3, 3, 8, 3, 8, 3],
    [8, 3, 3, 8, 3, 8, 8, 3, 8]
]

output = [['1' for _ in range(9)] for _ in range(7)]

# Mark cells with 8s on 3+ horizontal lines
for r in range(7):
    # Find consecutive 8s
    run_start = 0
    for c in range(9):
        if input_grid[r][c] != 8:
            if c - run_start >= 3:
                for k in range(run_start, c):
                    output[r][k] = '8'
            run_start = c
        c += 1
    # Last run
    if 9 - run_start >= 3:
        for k in range(run_start, 9):
            output[r][k] = '8'

# Mark cells with 8s on 3+ vertical lines
for c in range(9):
    run_start = 0
    for r in range(7):
        if input_grid[r][c] != 8:
            if r - run_start >= 3:
                for k in range(run_start, r):
                    output[k][c] = '8'
            run_start = r
        r += 1
    # Last run
    if 7 - run_start >= 3:
        for k in range(run_start, 7):
            output[k][c] = '8'

# Preserve diagonals (both main and anti)
for r in range(7):
    for c in range(9):
        if r == c or r + c == 8:
            output[r][c] = '8'

# Preserve 8s that are part of the "structure" (any horizontal line is already 8)
# Actually just set all 8s to 8
for r in range(7):
    for c in range(9):
        if input_grid[r][c] == 8:
            output[r][c] = '8'

# All 3s become 1 (unless already set to 8)
# Actually just replace remaining '1' with 1 as integer
final_grid = [[1 if x == '1' else int(x) for x in row] for row in output]

print("Output prediction:")
print(json.dumps(final_grid, indent=2))

